using Odc; using System.Text.Json;
if(args.Length<2){Console.Error.WriteLine("Uso: info|verify|extract|create|set-meta|remove-meta");return 2;}
try{switch(args[0]){case"info":Console.WriteLine(JsonSerializer.Serialize(OdcContainer.Info(args[1]),new JsonSerializerOptions{WriteIndented=true}));break;case"verify":if(!OdcContainer.Verify(args[1])){Console.WriteLine("INVALIDO");return 1;}Console.WriteLine("OK");break;case"extract":OdcContainer.Extract(args[1],args[2]);break;case"create":object? m=args.Length>3?JsonSerializer.Deserialize<JsonElement>(File.ReadAllText(args[3])):null;OdcContainer.Create(args[1],args[2],m,true);break;case"set-meta":OdcContainer.SetMetadata(args[1],JsonSerializer.Deserialize<JsonElement>(File.ReadAllText(args[2])));break;case"remove-meta":OdcContainer.SetMetadata(args[1],null);break;default:return 2;}return 0;}catch(Exception e){Console.Error.WriteLine("ERRO: "+e.Message);return 1;}
